function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const FIELD_TYPES = ['text', 'email', 'phone', 'textarea', 'select', 'radio', 'number'];
const MAP_TO = ['', 'full_name', 'email', 'phone', 'job_title'];

function parseAiContent(item) {
  const raw = item.json.output
    ?? item.json.text
    ?? item.json.message?.content
    ?? item.json.content
    ?? '';

  const trimmed = String(raw).trim();
  if (!trimmed) throw new Error('IA não retornou conteúdo');

  try {
    return JSON.parse(trimmed);
  } catch {
    const jsonMatch = trimmed.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('IA não retornou JSON');
    return JSON.parse(jsonMatch[0]);
  }
}

function normalizeField(field) {
  const f = field || {};
  return {
    id: f.id || uuid(),
    type: FIELD_TYPES.includes(f.type) ? f.type : 'text',
    label: f.label || 'Pergunta',
    placeholder: f.placeholder || '',
    required: !!f.required,
    options: Array.isArray(f.options) ? f.options.filter(Boolean) : undefined,
    mapTo: MAP_TO.includes(f.mapTo) ? f.mapTo : '',
  };
}

const parsed = parseAiContent($input.first());
const def = parsed.definition || parsed;
const steps = (def.steps || []).map((step) => ({
  id: step.id || uuid(),
  title: step.title || '',
  fields: (step.fields || []).map(normalizeField),
}));

if (!steps.length || !steps.some((s) => s.fields.length)) {
  throw new Error('Nenhuma pergunta gerada');
}

return [{
  json: {
    title: parsed.title || 'Formulário gerado',
    definition: {
      steps,
      thankYou: {
        title: def.thankYou?.title || 'Obrigado!',
        message: def.thankYou?.message || 'Recebemos suas informações.',
        buttonLabel: def.thankYou?.buttonLabel || '',
        redirectUrl: def.thankYou?.redirectUrl || '',
      },
      theme: {
        primary: def.theme?.primary || '#4f46e5',
        background: def.theme?.background || '',
        logoUrl: def.theme?.logoUrl || '',
      },
      settings: {
        source: def.settings?.source || 'website',
        description: def.settings?.description || '',
      },
    },
  },
}];
